import json
import re
from docx import Document

def fill_template(template_path, data_path, output_path):
    # Load data
    with open(data_path, 'r') as f:
        data = json.load(f)

    # Load template
    doc = Document(template_path)

    def replace_in_para(para):
        text = para.text

        # Handle conditional first
        if '{{IF_RELOCATION}}' in text:
            start_marker = '{{IF_RELOCATION}}'
            end_marker = '{{END_IF_RELOCATION}}'

            if data.get('RELOCATION_PACKAGE') == 'Yes':
                # Keep content, remove markers
                text = text.replace(start_marker, '').replace(end_marker, '')
            else:
                # Remove entire content between markers (or the whole paragraph if it's just that)
                # In this specific template, it's the whole content of the paragraph
                # Let's find the content between markers
                pattern = re.escape(start_marker) + r'.*?' + re.escape(end_marker)
                text = re.sub(pattern, '', text)

        # General placeholder replacement
        pattern = r'\{\{([A-Z_]+)\}\}'
        matches = re.findall(pattern, text)

        if not matches and text == para.text:
            return

        new_text = text
        for key in matches:
            placeholder = '{{' + key + '}}'
            if key in data:
                new_text = new_text.replace(placeholder, str(data[key]))

        if new_text != para.text:
            if para.runs:
                para.runs[0].text = new_text
                for run in para.runs[1:]:
                    run.text = ''
            else:
                para.text = new_text

    # Process paragraphs
    for para in doc.paragraphs:
        replace_in_para(para)

    # Process tables
    def process_table(table):
        for row in table.rows:
            for cell in row.cells:
                for para in cell.paragraphs:
                    replace_in_para(para)
                for nested in cell.tables:
                    process_table(nested)

    for table in doc.tables:
        process_table(table)

    # Process headers/footers
    for section in doc.sections:
        for para in section.header.paragraphs:
            replace_in_para(para)
        for para in section.footer.paragraphs:
            replace_in_para(para)

    doc.save(output_path)

if __name__ == "__main__":
    fill_template('offer_letter_template.docx', 'employee_data.json', 'offer_letter_filled.docx')

